(x, y, t) => {
  let nx = x * 0.02, ny = y * 0.02;
  let u = 0, v = 0;
  for (let i = 0; i < 5; i++) {
    let p = t * (0.25 + i * 0.07) + i * 1.257;
    let dx = nx - Math.cos(p) * 5, dy = ny - Math.sin(p * 0.73 + i) * 4;
    let d = Math.sqrt(dx * dx + dy * dy);
    u += Math.sin(d * 2.8 - t * 0.4 + i) * Math.exp(-d * 0.12);
    v += Math.cos(d * 3.5 + t * 0.35 + i * 0.7) * Math.exp(-d * 0.1);
  }
  u += Math.sin(nx * 2.0 + t * 0.18) * Math.sin(ny * 2.4 - t * 0.14) * 1.8;
  v += Math.cos(nx * 2.6 - t * 0.22) * Math.cos(ny * 1.9 + t * 0.16) * 1.4;
  let rd = 1.0 / (1.0 + Math.exp(-(u * u - v * v + u * v * 0.4) * 2.5));
  let detail = Math.sin(u * 4 + v * 3) * 0.08;
  let pv = Math.max(0, Math.min(1, rd + detail));
  let h = (pv * 0.85 + 0.52) % 1;
  let s = 0.65 + 0.25 * Math.sin(pv * 3.14);
  let l = 0.28 + 0.47 * pv;
  let c = (1 - Math.abs(2 * l - 1)) * s;
  let hh = h * 6;
  let xc = c * (1 - Math.abs(hh % 2 - 1));
  let m = l - c * 0.5;
  let r, g, b;
  if (hh < 1) { r = c; g = xc; b = 0; }
  else if (hh < 2) { r = xc; g = c; b = 0; }
  else if (hh < 3) { r = 0; g = c; b = xc; }
  else if (hh < 4) { r = 0; g = xc; b = c; }
  else if (hh < 5) { r = xc; g = 0; b = c; }
  else { r = c; g = 0; b = xc; }
  return [r + m, g + m, b + m];
}
